using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class NurseMoeReference {
 [Serializable]public class Reference{public Color albedo,packed;public int samples;public string method;}
 static Texture2D Read(Texture texture){var t=new Texture2D(2,2,TextureFormat.RGBA32,false,true);t.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(texture)));return t;}
 public static void Run(){try{
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NativeReferences/Moe/PrefabInstance/ZMoe.prefab"));go.GetComponent<Animator>().enabled=false;go.GetComponent<LODGroup>().ForceLOD(0);
  var renderer=go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0");var mesh=renderer.sharedMesh;var v=mesh.vertices;var uv=mesh.uv;var weights=mesh.boneWeights;var tri=mesh.GetTriangles(0);var world=v.Select(renderer.transform.TransformPoint).ToArray();var albedo=Read(renderer.sharedMaterial.GetTexture("_Albedo"));var packed=Read(renderer.sharedMaterial.GetTexture("_RMOE"));var result=new Reference{method="Area-weighted native Moe body-submesh-only intact cheek-to-forehead grey/olive skin on the intact side, olive intact skin subset (B/G <= 0.85; hair, red wounds, purple veins and dark scalp excluded; dense triangle normals normalized without the Vector3 small-area cutoff); front-facing samples exclude red wound pixels. Raw albedo and packed maps, no lighting."};double area=0;
  Func<Vector3,bool> skin=p=>p.x<-.012f&&p.x>-.075f&&p.y>1.66f&&p.y<1.77f;
  for(int j=0;j<tri.Length;j+=3){int a=tri[j],b=tri[j+1],c=tri[j+2];var normal=Vector3.Cross(world[b]-world[a],world[c]-world[a]);float normalLength=normal.magnitude;if(normalLength<1e-10f)continue;normal/=normalLength;if(normal.z<.25f)continue;float size=Vector3.Cross(v[b]-v[a],v[c]-v[a]).magnitude*.5f;for(int k=0;k<6;k++){float u=(k+.5f)/6f,w=(1-u)*.5f;if(!skin(world[a]*u+world[b]*w+world[c]*w))continue;var coord=uv[a]*u+uv[b]*w+uv[c]*w;var color=albedo.GetPixelBilinear(coord.x,coord.y);float hi=Mathf.Max(color.r,Mathf.Max(color.g,color.b)),lo=Mathf.Min(color.r,Mathf.Min(color.g,color.b));if(hi<.18f||hi>.85f||color.r>color.g*1.35f||color.b>color.g*.85f)continue;result.albedo+=color*size;result.packed+=packed.GetPixelBilinear(coord.x,coord.y)*size;area+=size;result.samples++;}}
  if(result.samples<12||area<=0)throw new Exception("Moe skin samples missing");result.albedo/=(float)area;result.packed/=(float)area;File.WriteAllText(NurseVisualOptimization.Out+"/moe-skin-reference.json",JsonUtility.ToJson(result,true));ExtractEye(go);NurseVisualOptimization.Render(go,"Moe_Current_Body",0,false);NurseVisualOptimization.Render(go,"MoeFace_Current",0,true);Debug.Log("MOE_SKIN_REFERENCE_READY "+result.albedo);
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static void ExtractEye(GameObject go){
  var r=go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(x=>x.name=="NormalEye");var m=NurseAnatomyRender.WorldSkin(r);var p=m.vertices;var uv=m.uv;var triangles=m.triangles;var points=p.Where(v=>v.x<-.005f).ToArray();if(points.Length<10)throw new Exception("Native Moe eye geometry missing");
  float cx=(points.Min(v=>v.x)+points.Max(v=>v.x))*.5f,cy=(points.Min(v=>v.y)+points.Max(v=>v.y))*.5f,span=Mathf.Max(points.Max(v=>v.x)-points.Min(v=>v.x),points.Max(v=>v.y)-points.Min(v=>v.y))*1.02f;
  var source=Read(r.sharedMaterial.GetTexture("_Albedo"));var packedSource=Read(r.sharedMaterial.GetTexture("_RMOE"));const int size=512;var pixels=new Color[size*size];var packed=new Color[size*size];var depth=Enumerable.Repeat(float.NegativeInfinity,size*size).ToArray();
  Func<Vector3,Vector2> screen=v=>new Vector2(.5f+(v.x-cx)/span,.5f+(v.y-cy)/span)*size;
  for(int j=0;j<triangles.Length;j+=3){int a=triangles[j],b=triangles[j+1],c=triangles[j+2];if(p[a].x>=-.005f||p[b].x>=-.005f||p[c].x>=-.005f)continue;var aa=screen(p[a]);var bb=screen(p[b]);var cc=screen(p[c]);float d=(bb.y-cc.y)*(aa.x-cc.x)+(cc.x-bb.x)*(aa.y-cc.y);if(Mathf.Abs(d)<1e-8f)continue;
   for(int y=Mathf.Max(0,Mathf.FloorToInt(Mathf.Min(aa.y,Mathf.Min(bb.y,cc.y))));y<=Mathf.Min(size-1,Mathf.CeilToInt(Mathf.Max(aa.y,Mathf.Max(bb.y,cc.y))));y++)for(int x=Mathf.Max(0,Mathf.FloorToInt(Mathf.Min(aa.x,Mathf.Min(bb.x,cc.x))));x<=Mathf.Min(size-1,Mathf.CeilToInt(Mathf.Max(aa.x,Mathf.Max(bb.x,cc.x))));x++){float u=((bb.y-cc.y)*(x+.5f-cc.x)+(cc.x-bb.x)*(y+.5f-cc.y))/d,v=((cc.y-aa.y)*(x+.5f-cc.x)+(aa.x-cc.x)*(y+.5f-cc.y))/d,w=1-u-v;if(u<0||v<0||w<0)continue;int i=y*size+x;float z=p[a].z*u+p[b].z*v+p[c].z*w;if(z<=depth[i])continue;depth[i]=z;var coord=uv[a]*u+uv[b]*v+uv[c]*w;pixels[i]=source.GetPixelBilinear(coord.x,coord.y);pixels[i].a=1;packed[i]=packedSource.GetPixelBilinear(coord.x,coord.y);}
  }
  var valid=Enumerable.Range(0,pixels.Length).Where(i=>pixels[i].a>0).ToArray();if(valid.Length<1000)throw new Exception("Native eye projection empty");Color rim=Color.clear;int count=0;foreach(int i in valid){float x=(i%size+.5f)/size-.5f,y=(i/size+.5f)/size-.5f;if(x*x+y*y>.12f){rim+=pixels[i];count++;}}if(count==0)throw new Exception("Native eye rim missing");rim/=count;rim.a=1;foreach(int i in Enumerable.Range(0,pixels.Length))if(pixels[i].a==0){pixels[i]=rim;packed[i]=new Color(.45f,0,1,0);}
  foreach(bool isPacked in new[]{false,true}){var t=new Texture2D(size,size,TextureFormat.RGBA32,false,true);t.SetPixels(isPacked?packed:pixels);t.Apply();File.WriteAllBytes(NurseVisualOptimization.Out+(isPacked?"/Moe_NativeEye_RMOE.png":"/Moe_NativeEye.png"),t.EncodeToPNG());}
  File.WriteAllText(NurseVisualOptimization.Out+"/native-eye-reference.txt","Moe NormalEye native albedo/RMOE reprojected from front hemisphere. No invented iris colour. Eye centre="+cx+","+cy+" span="+span+" covered="+valid.Length+".\n");UnityEngine.Object.DestroyImmediate(m);
 }

}
